from itertools import product

def minPath(grid, k):
    N = len(grid)
    flattened = [item for sublist in grid for item in sublist]
    positions = {value: (row, col) for row, row_val in enumerate(grid) for col, value in enumerate(row_val)}
    moves = [(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1) if abs(dx) + abs(dy) == 1]

    def bfs(start_value):
        start_pos = positions[start_value]
        visited = {str(start_pos): [start_value]}
        q = [([start_value], start_pos)]

        steps = 0
        while q:
            size = len(q)
            for _ in range(size):
                curr_path, curr_pos = q.pop(0)
                if len(curr_path) == k:
                    continue
                cx, cy = curr_pos
                for dx, dy in moves:
                    nx, ny = cx + dx, cy + dy
                    if 0 <= nx < N and 0 <= ny < N:
                        value = flattened[nx * N + ny]
                        if str((nx, ny)) not in visited or value < visited[str((nx, ny))][-1]:
                            path = curr_path + [value]
                            q.append((path, (nx, ny)))
                            visited[str((nx, ny))] = path
            steps += 1
            if steps >= k:
                break
        min_path = min(visited.values(), default=[], key=lambda x: x if len(x) == k else '')
        return min_path

    min_path = min([bfs(start_value) for start_value in range(1, N*N + 1)], key=lambda x: (len(x), x))
    return min_path
