import itertools

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y, steps, path):
        if len(path) == steps:
            results.append(path[:])
            return
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                dfs(nx, ny, steps, path + [grid[nx][ny]])

    results = []
    for i in range(N):
        for j in range(N):
            dfs(i, j, k, [grid[i][j]])

    results.sort()
    return results[0]
