    result = []
    min_even_value = float('inf')
    min_index = -1

    for i, value in enumerate(arr):
        if value % 2 == 0 and value <= min_even_value:
            if value < min_even_value or i < min_index:
                min_even_value = value
                min_index = i

    if min_even_value != float('inf'):
        result = [min_even_value, min_index]

    return result
