def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    from collections import defaultdict

    if not test:
        return {}
    # Split the string into a list of letters
    letters_list = test.split(" ")
    # Use a defaultdict to keep count of each letter
    count = defaultdict(int)
    for letter in letters_list:
        if letter:  # Ensure the letter is not an empty string
            count[letter] += 1
    # Find the maximum count
    max_count = max(count.values()) if count.values() != [] else 0

    # Create a list of letters with the max_count occurrences
    most_common_letters = {k: v for k, v in count.items() if v == max_count}

    return most_common_letters

