def max_fill(grid, capacity):
    import math
    def count_water_units(row):
        return sum(row)

    total_iterations = 0
    for row in grid:
        water_units = count_water_units(row)
        iterations = math.ceil(water_units / capacity)
        total_iterations += iterations

    return total_iterations

