    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    def is_prime(n):
        """Check if a number is prime."""
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    factors = []
    for i in range(2, a + 1):
        if len(factors) > 3:
            break
        if a % i == 0 and is_prime(i):
            factors.append(i)
            a //= i

    return len(factors) == 3 and a == 1
