def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    if n < 8:
        return False
    elif n % 2 != 0:
        return False
    else:
        # n can be represented as a sum of 4 even numbers if (n - smallest sum of 4 even numbers) is divisible by 2 
        return (n - sum(range(2, 9, 2))) % 2 == 0
