def exchange(lst1, lst2):
    odd_indices_lst1 = [i for i, num in enumerate(lst1) if num % 2 != 0]
    even_only = len(odd_indices_lst1) == 0
    found_exchange = False

    if len(lst2) < len(lst1):
        return "NO"

    for idx in odd_indices_lst1:
        if any(element % 2 == 0 for element in lst2):
            found_exchange = any(lst1[idx] == x or (x % 2 == 0 and lst2.index(x) != idx) for x in lst2)
            if found_exchange:
                break
        else:
            return "NO"

    if any(lst1.count(i) > lst2.count(j) for i, j in zip([i for i in lst1 if i % 2 == 0], lst2)):
        return "NO"

    return "YES" if found_exchange or even_only else "NO"
