from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    result = []
    stack = []
    for i, c in enumerate(paren_string):
        if c == '(':
            stack.append(i)
        elif c == ')':
            if stack:
                start_idx = stack.pop()
                group = paren_string[start_idx:i+1]
                if not stack:
                    result.append(group)
    return result
