    for bracket in string:
        if bracket == '[':
            stack.append(bracket)
        elif stack:
            stack.pop()
        # if the stack is empty and we encounter a ']', it means there are unbalanced brackets
        elif bracket == ']':
            return False
    # if the stack is not empty at the end, it means there are unbalanced brackets
    if stack:
        return True
    # Check if there is at least one nested bracket
    nested = False
    temp_stack = []
    for bracket in string:
        if bracket == '[':
            temp_stack.append(bracket)
        elif temp_stack:
            temp_stack.pop()
            # If the stack is not empty after popping, it indicates at least one pair of brackets is nested
            nested = True
        else:
            nested = False
            break
    return nested
