def fib4(n: int):
    if n < 2:
        return n % 2
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initialize the first four values of the sequence
    fib4_values = [0, 0, 2, 0]

    # Compute the sequence up to n
    for i in range(4, n + 1):
        fib4_values[i % 4] = fib4_values[(i - 1) % 4] + fib4_values[(i - 2) % 4] + fib4_values[(i - 3) % 4] + fib4_values[(i - 4) % 4]

    # Return the nth value
    return fib4_values[n % 4]
