from collections import defaultdict

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    graph = defaultdict(list)
    values = {}

    for i in range(N):
        for j in range(N):
            values[(i, j)] = grid[i][j]
            for dx, dy in directions:
                ni, nj = i + dx, j + dy
                if 0 <= ni < N and 0 <= nj < N:
                    graph[(i, j)].append((ni, nj))

    def bfs(start):
        queue = [(values[start], [values[start]], start)]
        visited = defaultdict(lambda: (float('inf'), []))
        visited[start] = (values[start], [values[start]])

        for _ in range(k - 1):
            new_queue = []
            for val, path, node in queue:
                for neighbor in graph[node]:
                    new_val = values[neighbor]
                    new_path = path + [new_val]
                    if new_val < visited[neighbor][0] or (new_val == visited[neighbor][0] and new_path < visited[neighbor][1]):
                        visited[neighbor] = (new_val, new_path)
                        new_queue.append((new_val, new_path, neighbor))
            queue = sorted(new_queue)[:N*N]

        return visited

    min_path = None
    for i in range(N):
        for j in range(N):
            visited = bfs((i, j))
            for val, path in visited.values():
                if min_path is None or path < min_path:
                    min_path = path

    return min_path
