def tri(n):
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]
    elif n == 2:
        return [1, 3, 2]
    lookup = [None for _ in range(n + 1)]
    lookup[0], lookup[1], lookup[2] = 1, 3, 2
    for i in range(3, n + 1):
        if i % 2 == 0:
            lookup[i] = int((i / 2)) + 1
        else:
            lookup[i] = lookup[i - 1] + lookup[i - 2] + lookup[i + 1 -1]
    return lookup[:n + 1]

# Test cases
