def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list that has the odd numbers in collatz sequence.
    """
    def generate_collatz(o):
        yield o
        while o != 1:
            if o % 2 == 0:
                o = o // 2
                if o % 2 != 0:
                    yield o
            else:
                o = 3 * o + 1
                yield o

    result = []
    for odd in generate_collatz(n):
        if odd not in result:
            result.append(odd)
    result.sort()
    return result
