from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    def max_depth(chars: str) -> int:
        max_depth_measure = 0
        current_depth_measure = 0

        for char in chars:
            if char == '(':
                current_depth_measure += 1
                max_depth_measure = max(max_depth_measure, current_depth_measure)
            elif char == ')':
                current_depth_measure -= 1
        return max_depth_measure

    results = []
    for group in paren_string.split(' '):
        depth = max_depth(group)
        if depth > 0:
            results.append(depth)
    return results
