            return [0]
        is_negative = n < 0
        digits = []
        n_str = str(abs(n))
        for digit_str in n_str:
            digit = int(digit_str)
            if is_negative:
                if len(digits) == 0:
                    digits.append(-digit)
                else:
                    digits.append(digit)
            else:
                digits.append(digit)
        return digits

    count = 0
    for num in arr:
        if sum(signed_digits(num)) > 0:
            count += 1
    return count
