from collections import defaultdict

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    value_to_position = defaultdict(list)
    for r in range(N):
        for c in range(N):
            value_to_position[grid[r][c]].append((r, c))

    def get_neighbors(r, c):
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def get_initial_states():
        states = []
        for value in range(1, N * N + 1):
            for r, c in value_to_position[value]:
                states.append((value, r, c))
        return states

    def compare_paths(path1, path2):
        for v1, v2 in zip(path1, path2):
            if v1 < v2:
                return -1
            elif v1 > v2:
                return 1
        return 0

    initial_states = get_initial_states()
    min_heap = [(state[0], [state[0]], state[1], state[2]) for state in initial_states]
    heapq.heapify(min_heap)

    while min_heap:
        value, path, r, c = heapq.heappop(min_heap)
        if len(path) == k:
            continue
        for nr, nc in get_neighbors(r, c):
            next_value = grid[nr][nc]
            next_path = path + [next_value]
            heapq.heappush(min_heap, (next_value, next_path, nr, nc))

    final_paths = [heapq.heappop(min_heap)[1] for _ in range(len(min_heap))]
    final_paths.sort(key=functools.cmp_to_key(compare_paths))

    return final_paths[0]
