    shift_vowels = "cginlorsuay"
    upper_shift = {l: u for l, u in zip(vowels, shift_vowels)}
    for v in set(vowels + upper_shift.keys()) - set(vowels):
        upper_shift[chr(ord(v) - ord('a') + ord('A'))] = upper_shift[v].upper()
    encoded_message = ""
    for char in message:
        if char.isalpha():
            new_char = char.swapcase()
            if char.lower() in vowels:
                new_char = upper_shift[char][0]
            encoded_message += new_char
        else:
            encoded_message += char
    return encoded_message

