def fib(n: int):
    """Return n-th Fibonacci number.
    >>> fib(10)
    55
    >>> fib(1)
    1
    >>> fib(8)
    21
    """
    def fibonacci(num):
        if num <= 0:
            return 0
        elif num == 1:
            return 1
        else:
            a, b = 0, 1
            for _ in range(2, num + 1):
                a, b = b, a + b
            return b

    return fibonacci(n)
