from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    from itertools import accumulate
    deepest_nesting = []
    for parens in paren_string.split():
        active = []
        max_active = 0
        for p in parens:
            if p == '(':
                active.append(p)
            else:
                active.pop()
            if len(active):
                max_active = max_active if max_active + len(parens) >= len(active) else len(active)  
        max_level = max(accumulate(p == '(' for p in parens), default=0) + 1
        deepest_nesting.append(max(max_level, max_active))
    return deepest_nesting
