from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def analyze_parens(group: str) -> int:
        depth = 0
        max_depth = 0
        for char in group:
            if char == "(":
                depth += 1
                max_depth = max(max_depth, depth)
            elif char == ")":
                if depth > 0:
                    depth -= 1
                else:
                    print("Invalid: Too many closing parentheses at")
        return max_depth
    groups = paren_string.split(" ")
    results = []
    for group in groups:
        results.append(analyze_parens(group))
    return results
