def solve(s):
    """Transform a given string s by reversing the case of its letters.
    If the string contains no letters, reverse the string.
    """
    has_letters = False
    for char in s:
        if char.isalpha():
            has_letters = True
            break
    if has_letters:
        modified = ""
        for char in s:
            if char.isalpha():
                if char.islower():
                    modified += char.upper()
                else:
                    modified += char.lower()
            else:
                modified += char
        return modified
    else:
        return s[::-1]

