def compare_one(a, b):
    """
    This function compares two numbers that can be integers, floats or strings and returns the larger one in the same format as it was received. Returns None if they are equal.
    """
    def convert_to_float(x):
        if isinstance(x, str):
            if ',' in x:
                x = x.replace(',', '.')
        return float(x)

    a_float = convert_to_float(a)
    b_float = convert_to_float(b)

    if a_float > b_float:
        return a
    elif b_float > a_float:
        return b
    return None

# Example Usage:
# compare_one(1, 2.5) ➞ 2.5
# compare_one(1, "2,3") ➞ "2,3"
# compare_one("5,1", "6") ➞ "6"
# compare_one("1", 1) ➞ None
