from itertools import product

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    best_path = [None] * k

    def explore(x, y, path):
        nonlocal best_path
        if len(path) == k:
            if best_path[0] is None or path < best_path:
                best_path = path.copy()
            return

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                explore(nx, ny, path + [grid[ny][nx]])

    for i, j in product(range(N), repeat=2):
        explore(i, j, [grid[j][i]])

    return best_path

