from itertools import product
from heapq import heappush, heappop

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def get_neighbors(r, c):
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def get_path_value(path):
        return tuple(grid[r][c] for r, c in path)

    min_path = None
    min_value = float('inf')

    for r, c in product(range(N), repeat=2):
        current_path = [(r, c)]
        current_value = [grid[r][c]]
        current_heap = [(grid[r][c], (r, c))]

        for _ in range(k - 1):
            new_heap = []
            while current_heap:
                value, (r, c) = heappop(current_heap)
                for nr, nc in get_neighbors(r, c):
                    if (nr, nc) not in current_path:
                        new_value = current_value + [grid[nr][nc]]
                        new_path = current_path + [(nr, nc)]
                        if new_value < min_value:
                            min_value = new_value
                            min_path = new_path
                        heappush(new_heap, (new_value[0], (nr, nc)))
            current_heap = new_heap

        if get_path_value(current_path) < min_value:
            min_value = get_path_value(current_path)
            min_path = current_path

    return [grid[r][c] for r, c in min_path]
