from collections import deque
import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    cells = [(value, r, c) for r, row in enumerate(grid) for c, value in enumerate(row)]
    cells.sort()

    def get_neighbors(r, c):
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def bfs(start):
        queue = deque([(start, [cells[start][0]])])
        visited = {start}
        paths = []
        while queue:
            current, path = queue.popleft()
            if len(path) == k:
                paths.append(path)
                continue
            for neighbor in get_neighbors(cells[current][1], cells[current][2]):
                ncell = next(i for i, (v, r, c) in enumerate(cells) if r == neighbor[0] and c == neighbor[1])
                if ncell not in visited:
                    visited.add(ncell)
                    queue.append((ncell, path + [cells[ncell][0]]))
        return paths

    min_paths = bfs(0)
    min_paths.sort()
    return min_paths[0]
