from itertools import product

def minPath(grid, k):
    N = len(grid)
    positions = {}
    for i in range(N):
        for j in range(N):
            positions[grid[i][j]] = (i, j)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid_position(x, y):
        return 0 <= x < N and 0 <= y < N

    def dfs(current_val, current_path, visited):
        if len(current_path) == k:
            return current_path
        x, y = positions[current_val]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid_position(nx, ny) and grid[nx][ny] not in visited:
                next_val = grid[nx][ny]
                visited.add(next_val)
                result = dfs(next_val, current_path + [next_val], visited)
                visited.remove(next_val)
                if len(result) == k:
                    return result
        return current_path

    min_path = None
    for val in range(1, N*N + 1):
        visited = {val}
        path = dfs(val, [val], visited)
        if min_path is None or path < min_path:
            min_path = path
    return min_path
