        return "".join(chr(ord(start) + off) for off in range(26))

    regular_chars = "abcdefghijklmnopqrstuvwxyz"
    shifted_chars = shifted_alphabet(regular_chars[4])

    tr = str.maketrans(regular_chars + regular_chars.upper(), 
                        shifted_chars + shifted_chars.upper())
    return s.translate(tr)
