from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    groups = []
    stack = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            if stack:
                current_group += char
            stack.append(char)
        elif char == ")":
            if stack:
                current_group += char
                stack.pop()
                if not stack and len(groups) > 0:
                    groups.append(current_group)
                    current_group = ""
            else:
                if current_group:
                    groups.append(current_group)
                    current_group = ""
                current_group += char
                stack.append(char)

    if current_group:
        groups.append(current_group)

    return groups
```

