from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    groups = []
    stack = []
    group = ""
    for char in paren_string:
        if char == "(":
            if stack:
                group += char
            stack.append(char)
        elif char == ")":
            if stack:
                group += char
                stack.pop()
                if not stack and group:
                    groups.append(group)
                    group = ""
            else:
                raise ValueError("Unbalanced parentheses")
    return groups
```

