def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiouAEIOU'
    encoded_message = []

    for char in message:
        # Swap case of letters
        if char.isalpha():
            char = char.swapcase()
            if char in vowels:
                # Determine the letter 2 places ahead in the alphabet
                if char == 'a':
                    char = 'c'
                elif char == 'A':
                    char = 'C'
                elif char == 'e':
                    char = 'g'
                elif char == 'E':
                    char = 'G'
                elif char == 'i':
                    char = 'k'
                elif char == 'I':
                    char = 'K'
                elif char == 'o':
                    char = 'q'
                elif char == 'O':
                    char = 'Q'
                elif char == 'u':
                    char = 'w'
                elif char == 'U':
                    char = 'W'
                elif char == 'y':
                    char = 'a'
                elif char == 'Y':
                    char = 'A'
                else:
                    index = vowels.find(char) + 2
                    char = vowels[index] if index < len(vowels) else char

        encoded_message.append(char)

    return ''.join(encoded_message)

# Test cases
