def numerical_letter_grade(grades):
    gpa_to_grade = [
        (4.0, 'A+'), (3.7, 'A'), (3.3, 'A-'), (3.0, 'B+'), (2.7, 'B'),
        (2.3, 'B-'), (2.0, 'C+'), (1.7, 'C'), (1.3, 'C-'), (1.0, 'D+'),
        (0.7, 'D'), (0.0, 'D-'), (float('-inf'), 'E')
    ]

    def find_letter_grade(gpa):
        for gpa_threshold, letter_grade in gpa_to_grade:
            if gpa >= gpa_threshold:
                return letter_grade
        return 'E'

    return [find_letter_grade(gpa) for gpa in grades]

