from typing import List, Tuple
import heapq


def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    if not numbers or len(numbers) < 2:
        return ()
    heapq.heapify(numbers)
    first_closest = heapq.heappop(numbers)
    second_closest = heapq.heappop(numbers)
    min_distance_pair = (first_closest, second_closest)

    while numbers:
        next_element = heapq.heappop(numbers)
        if abs(next_element - first_closest) < abs(second_closest - first_closest):
            min_distance_pair = (first_closest, next_element) if first_closest <= next_element else (next_element, first_closest)
        first_closest = second_closest
        second_closest = next_element

    if abs(min_distance_pair[1] - first_closest) < abs(second_closest - next_element):
        min_distance_pair = (first_closest, second_closest) if first_closest <= second_closest else (second_closest, first_closest)

    return min_distance_pair
