from functools import total_ordering

@total_ordering
class CustomInt:
    def __init__(self, value):
        self.value = value

    def __eq__(self, other):
        return self.value == other.value

    def __lt__(self, other):
        ones_self = bin(self.value).count('1')
        ones_other = bin(other.value).count('1')
        return ones_self < ones_other or (ones_self == ones_other and self.value < other.value)

def sort_array(arr):
    custom_arr = [CustomInt(x) for x in arr]
    custom_arr.sort()
    return [x.value for x in custom_arr]

# Test cases
print(sort_array([1, 5, 2, 3, 4]))  # Expected: [1, 2, 3, 4, 5]
print(sort_array([-2, -3, -4, -5, -6]))  # Expected: [-6, -5, -4, -3, -2]
print(sort_array([1, 0, 2, 3, 4]))  # Expected: [0, 1, 2, 3, 4]

