from collections import deque

def sum_of_digits(n):
    total = 0
    n_str = str(n)
    for c in n_str:
        if c.isdigit():
            total += int(c)
        else:
            total += (-int(c[1:]) if c.startswith('-') else 0)
    return total

def order_by_points(nums):
    num_queue = deque()
    for index, num in enumerate(nums):
        num_queue.append((index, num))

    # Sort first by sum of digits, then by original index
    sorted_nums = sorted(num_queue, key=lambda x: (sum_of_digits(x[1]), x[0]))
    result = [0] * len(nums)
    for index, num in sorted_nums:
        result[index] = num
    return result

# Example usage
if __name__ == "__main__":
    print(order_by_points([1, 11, -1, -11, -12]))  # Output: [-1, -11, 1, -12, 11]
    print(order_by_points([]))  # Output: []
