import math

def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero finds x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and the guarantee of a solution.
    """
    def bisection(a, b):
        if poly(xs, a) * poly(xs, b) >= 0:
            return None
        while abs(b - a) > 1e-6:
            midpoint = (a + b) / 2.0
            if poly(xs, midpoint) == 0:
                return round(midpoint, 6)
            elif poly(xs, a) * poly(xs, midpoint) < 0:
                b = midpoint
            else:
                a = midpoint
        return round((a + b) / 2.0, 6)

    # Find initial approximation interval
    delta = 1.0
    low, high = -100, 100
    while poly(xs, low) * poly(xs, low + delta) > 0 and poly(xs, high) * poly(xs, high + delta) > 0:
        delta *= 2
    if delta > 1:
        a = math.floor(high)
        b = math.ceil(low)
        while b > a and poly(xs, a) * poly(xs, a + 1) > 0:
            a += 1
        while b > a and poly(xs, b) * poly(xs, b - 1) > 0:
            b -= 1
    else:
        if poly(xs, low) == 0:
            return low

