    and false otherwise.
    Knowing that (a) is less than 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                return False
        return True

    count = 0
    divisor = 2
    factors = []

    while a > 1 and divisor <= a:
        while a % divisor == 0 and is_prime(divisor):
            a //= divisor
            factors.append(divisor)
        divisor += 1

    for factor in factors:
        if a % factor == 0 and is_prime(a):
            return False
    return len(factors) == 3
