    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    # Normalize string inputs and split variables
    if isinstance(a, str):
        a = float(a.replace(',', '.'))
    if isinstance(b, str):
        b = float(b.replace(',', '.'))

    # Determine larger value
    if a == b:
        return None
    elif a > b:
        return a if not isinstance(a, float) else str(a).replace('.', ',')
    else:
        return b if not isinstance(b, float) else str(b).replace('.', ',')
