def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1  # Only '1' satisfies the condition for 1-digit numbers
    total_count = 0
    for i in range(n):
        if i == 0:  # For numbers that start with 1
            total_count += 8 * (10 ** (i))
        elif i == n - 1:  # For numbers that end with 1
            total_count += 8 * (10 ** (i))
        else:  # Double counting the intersection (numbers that start and end with 1)
            total_count += 2 * (10 ** (i))
    return total_count

# Correcting the logic as both start and end conditions overlap for single insertion
def starts_one_ends_correct(n):
    if n == 1:
        return 1 # Only '1' satisfies the condition for 1-digit number
    count = 2 * (9 ** (n - 1))  # Count numbers starting or ending with 1
    if n > 1:
        count -= 9 ** (n - 2)  # Correct overlap (numbers starting and ending with 1)
    return count

# Simplified approach
def starts_one_ends_simplified(n):
    if n == 1:
        return 1
    return 2 * (10 ** (n - 1)) - (10 ** (n - 2))

# Most efficient way
def starts_one_ends_efficient(n):
    if n == 1:
        return 1
    return 2 * (9 ** (n - 1)) + (10 ** (n - 1) - 9 ** (n - 1))
