import itertools
import math
from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    moves = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, down, left, right
    visited = [[False] * N for _ in range(N)]

    def get_neighbors(x, y):
        for dx, dy in moves:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                yield nx, ny

    def dfs(x, y, k, path):
        if k == 0:
            return path
        min_path = None
        for nx, ny in get_neighbors(x, y):
            if not visited[nx][ny]:
                visited[nx][ny] = True
                new_path = dfs(nx, ny, k - 1, path + [grid[nx][ny]])
                if min_path is None or new_path < min_path:
                    min_path = new_path
                visited[nx][ny] = False
        return min_path

    for start_x in range(N):
        for start_y in range(N):
            visited[start_x][start_y] = True
            result = dfs(start_x, start_y, k - 1, [grid[start_x][start_y]])
            visited[start_x][start_y] = False
            if min_path is None or result < min_path:
                min_path = result
    return min_path
