    if n < 0:
        return []
    table = [1, 3]

    def inner(tri_table, index):
        if index > n:
            return tri_table
        if index % 2 == 1:
            if index <= 3:
                tri_table.append(tri_table[-1] + tri_table[-2] + max(tri_table) + 1)
            else:
                tri_table.append(tri_table[-1] + tri_table[-2] + tri_table[-3])
        else:
            tri_table.append(1 + index // 2)

        return inner(tri_table, index + 1)

    result = inner(table, len(table))

    return result[:n + 1]

