        if 'a' <= c <= 'z':
            offset = ord('a')
        elif 'A' <= c <= 'Z':
            offset = ord('A')
        else:
            return c

        rotated = (ord(c) - offset + (2 * 2)) % 26 + offset
        return chr(rotated)

    return ''.join(rotate_char(c) for c in s)
