import heapq
from collections import defaultdict

def minPath(grid, k):
    N = len(grid)
    cell_positions = {}
    for i in range(N):
        for j in range(N):
            cell_positions[grid[i][j]] = (i, j)

    def get_neighbors(x, y):
        for dx, dy in [(0, -1), (-1, 0), (0, 1), (1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                yield nx, ny

    def bfs(start_value):
        visited = set()
        queue = [(start_value, [start_value])]
        min_path = None

        while queue:
            value, path = heapq.heappop(queue)
            if len(path) > k:
                continue
            if len(path) == k:
                if min_path is None or path < min_path:
                    min_path = path
                continue

            x, y = cell_positions[value]
            for nx, ny in get_neighbors(x, y):
                next_value = grid[nx][ny]
                if next_value not in visited:
                    visited.add(next_value)
                    heapq.heappush(queue, (next_value, path + [next_value]))

        return min_path

    min_path = None
    for value in sorted(grid[0]):
        path = bfs(value)
        if min_path is None or path < min_path:
            min_path = path

    return min_path
