import copy
from itertools import product

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    visited = [[False] * N for _ in range(N)]
    min_path = [float('inf')] * k

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def dfs(x, y, path, length):
        nonlocal min_path
        if length == k:
            for i in range(k):
                if path[i] < min_path[i]:
                    min_path = copy.deepcopy(path)
                    break
                elif path[i] > min_path[i]:
                    break
            return
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and not visited[nx][ny]:
                visited[nx][ny] = True
                path[length] = grid[nx][ny]
                dfs(nx, ny, path, length + 1)
                visited[nx][ny] = False

    for i, j in product(range(N), repeat=2):
        visited[i][j] = True
        dfs(i, j, [grid[i][j]], 1)
        visited[i][j] = False
    return min_path
