def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = {"a": "c", "e": "g", "i": "k", "o": "q", "u": "a",
              "A": "c", "E": "g", "I": "k", "O": "q", "U": "a"}
    swapped_and_encoded = []

    for char in message:
        if char in vowels:
            char = vowels[char]
            if char.isupper():
                swapped_and_encoded.append(char.lower())
            else:
                swapped_and_encoded.append(char.upper())
        else:
            if char.isalpha():
                char = char.swapcase()
            swapped_and_encoded.append(char)

    return ''.join(swapped_and_encoded)
