    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    count = 0
    for i in range(2, int(sqrt(a)) + 1):
        if a % i == 0 and is_prime(i):
            a /= i
            count += 1
            if count > 3:
                return False
            if a == 1:
                break
    if a > 1 and is_prime(a):
        count += 1
    return count == 3
