from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    dir = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y, k, visit_set, val):
        if k == 0:
            return list(val)

        result = None
        for i, j in dir:
            nx, ny = x + i, y + j
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visit_set:
                visit_set.add((nx, ny))
                path = (dfs(nx, ny, k - 1, visit_set, val + [grid[nx][ny]]))
                if result is None or path < result:
                    result = path
                visit_set.discard((nx, ny))

        return result if result else val

    return min([dfs(i, j, k - 1, {(i, j)}, [grid[i][j]]) for j in range(n) for i in range(n)])
