    if s[i] is a letter, reverse its case from lower to upper or vise versa, 
    otherwise keep it as it is.
    If the string contains no letters, reverse the string.
    The function should return the resulted string.
    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    has_letters = False
    new_s = list(s)

    for c in s:
        if c.isalpha():
            has_letters = True
            if c.islower():
                new_s[s.index(c)] = c.upper()
            else:
                new_s[s.index(c)] = c.lower()

    if not has_letters:
        new_s = new_s[::-1]

