def change_base(x: int, base: int) -> str:
    if base < 2 or base > 9:
        raise ValueError('Base must be between 2 and 9')

    result = ''
    if x == 0:
        return '0'
    while x > 0:
        digit = x % base
        x //= base
        result = str(digit) + result
    return result
