from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
    value_to_pos = {}
    for r in range(N):
        for c in range(N):
            value_to_pos[grid[r][c]] = (r, c)

    def is_valid(r, c):
        return 0 <= r < N and 0 <= c < N

    def dfs(r, c, steps_left, path, min_path):
        nonlocal value_to_pos
        if steps_left == 0:
            if len(path) < len(min_path) or (len(path) == len(min_path) and path < min_path):
                min_path[:] = path
            return

        value = grid[r][c]
        next_steps = steps_left - 1
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                dfs(nr, nc, next_steps, path + [grid[nr][nc]], min_path)

    min_path = [float('inf')] * k
    for r in range(N):
        for c in range(N):
            dfs(r, c, k - 1, [grid[r][c]], min_path)

    return min_path
