import heapq
from collections import defaultdict

def minPath(grid, k):
    N = len(grid)
    position = {}
    for i in range(N):
        for j in range(N):
            position[grid[i][j]] = (i, j)

    def neighbors(x, y):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                yield grid[nx][ny], nx, ny

    def compare_paths(path1, path2):
        for v1, v2 in zip(path1, path2):
            if v1 < v2:
                return -1
            elif v1 > v2:
                return 1
        return 0

    start_value = min(grid[0][0], grid[0][1], grid[1][0], grid[1][1])
    start_x, start_y = position[start_value]

    heap = []
    for v, x, y in neighbors(start_x, start_y):
        heapq.heappush(heap, [v])

    while k > 1:
        new_heap = []
        while heap:
            path = heap.pop(0)
            for v, x, y in neighbors(position[path[-1]], 0):
                new_path = path + [v]
                if compare_paths(new_path, new_heap[0]) < 0 if new_heap else -1:
                    if len(new_heap) < k:
                        heapq.heappush(new_heap, new_path)
                    else:
                        heapq.heappushpop(new_heap, new_path)
        heap = new_heap
        k -= 1

    final_paths = [heapq.heappop(heap) for _ in range(len(heap))]
    final_paths.sort(key=len, reverse=True)
    return final_paths[0]

