import numpy as np

def minPath(grid, k):
    n = len(grid)
    grid = np.array(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()

    def dfs(x, y, path, step):
        if step == k:
            return path
        min_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [grid[nx][ny]]
                if tuple(new_path) not in visited:
                    visited.add(tuple(new_path))
                    result = dfs(nx, ny, new_path, step + 1)
                    if min_path is None or result < min_path:
                        min_path = result
        return min_path

    min_path = None
    for i in range(n):
        for j in range(n):
            result = dfs(i, j, [grid[i][j]], 1)
            if min_path is None or result < min_path:
                min_path = result
    return min_path
