    """
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, num):
            if num % i == 0:
                return False
        return True

    primes = []
    for number in range(2, n):
        if is_prime(number):
            primes.append(number)
            if len(primes) == n:
                break
    return primes

