from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    index = 0
    stack = []
    paren_string = paren_string.replace(" ", "")

    for i, char in enumerate(paren_string):
        if char == "(":
            stack.append(char)
        elif char == ")":
            if stack:
                stack.pop()
            else:
                index = i
                break

    if stack:
        result.append(paren_string[:index+1])
        return result

    for i in range(len(paren_string)):
        if paren_string[i] == "(":
            index = i
            bal = 0
            for j in range(i, len(paren_string)):
                if paren_string[j] == "(":
                    bal += 1
                elif paren_string[j] == ")":
                    bal -= 1
                if bal == 0:
                    result.append(paren_string[index:j+1])
                    index = j + 1
                    break
    return result
