def separate_paren_groups(paren_string: str) -> List[str]:
    parens = paren_string.replace(" ", "")
    groups = []
    stack = []
    depth = 0

    for char in parens:
        if char == '(':
            if depth > 0:
                stack.append(char)
            depth += 1
        else:
            depth -= 1
            if depth > 0:
                stack.append(char)
            else:
                groups.append(''.join(stack))
                stack = []
                depth = 0

