    if not match:
        return False

    month, day, year = match.groups()
    month = int(month)
    day = int(day)

    # Check month validity
    if month < 1 or month > 12:
        return False

    # Check day validity
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day > 30:
            return False
    else:  # month == 2 (February)
        if day > 29:
            return False

    return True
