import re

def valid_date(date):
    if not date:
        return False
    # Check the format of the date string
    if not re.match(r'\d{2}-\d{2}-\d{4}', date):
        return False
    mm, dd, yyyy = map(int, date.split('-'))
    # Check the month
    if not 1 <= mm <= 12:
        return False
    # Check the year
    if len(yyyy) != 4:
        return False
    # Check the days based on the month
    if mm in [1, 3, 5, 7, 8, 10, 12]:
        if not (1 <= dd <= 31):
            return False
    elif mm in [4, 6, 9, 11]:
        if not (1 <= dd <= 30):
            return False
    else:  # For month 2, consider it as non-leap year (always 28 days)
        if not (1 <= dd <= 28):
            return False
    return True

# Test cases
