from sympy import isprime

def fib(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib(n-1) + fib(n-2)

def prime_fib(n: int):
    count = 0
    i = 0
    while True:
        fib_num = fib(i)
        if isprime(fib_num):
            count += 1
            if count == n:
                return fib_num
        i += 1

# Test cases
